import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';

const dbPath = process.env.DB_PATH || './data/workboard.sqlite';
if (dbPath !== ':memory:') mkdirSync(dirname(resolve(dbPath)), { recursive: true });
const db = new DatabaseSync(dbPath);
db.exec('PRAGMA foreign_keys = ON');
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL
)`);
if (!db.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'archived')) {
  db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
}
if (!db.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'default_priority')) {
  db.exec("ALTER TABLE projects ADD COLUMN default_priority TEXT NOT NULL DEFAULT 'Normal' CHECK (default_priority IN ('Low', 'Normal', 'High'))");
}
const getProject = db.prepare('SELECT id, name, archived, default_priority FROM projects WHERE id = ?');
const updateProject = db.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const setDefaultPriority = db.prepare('UPDATE projects SET default_priority = ? WHERE id = ?');
const renameProject = db.prepare('UPDATE projects SET name = ? WHERE id = ?');
const createProject = db.prepare('INSERT INTO projects (name) VALUES (?)');
db.exec(`CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id),
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
);
CREATE INDEX IF NOT EXISTS tasks_project_id ON tasks(project_id)`);
if (!db.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'priority')) {
  db.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))");
}
if (!db.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'due_date')) {
  db.exec("ALTER TABLE tasks ADD COLUMN due_date TEXT NOT NULL DEFAULT ''");
}
if (!db.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'position')) {
  db.exec('ALTER TABLE tasks ADD COLUMN position INTEGER NOT NULL DEFAULT 0; UPDATE tasks SET position = id');
}
// Retain positions even while tasks are away. Seed existing tasks without changing
// their current order when upgrading a database from an earlier checkpoint.
db.exec(`BEGIN;
  CREATE TABLE IF NOT EXISTS task_positions (
    task_id INTEGER NOT NULL REFERENCES tasks(id),
    project_id INTEGER NOT NULL REFERENCES projects(id),
    position INTEGER NOT NULL,
    PRIMARY KEY (task_id, project_id)
  );
  CREATE INDEX IF NOT EXISTS task_positions_project ON task_positions(project_id, position);
  INSERT OR IGNORE INTO task_positions (task_id, project_id, position)
    SELECT id, project_id, position FROM tasks;
  COMMIT;`);
const listProjects = db.prepare(`SELECT projects.id, projects.name, projects.archived, projects.default_priority,
  COUNT(tasks.id) AS total, COALESCE(SUM(tasks.completed), 0) AS completed
  FROM projects LEFT JOIN tasks ON tasks.project_id = projects.id
  GROUP BY projects.id ORDER BY projects.id`);
const listTasks = db.prepare('SELECT id, title, completed, priority, due_date FROM tasks WHERE project_id = ? ORDER BY position, id');
const getTask = db.prepare('SELECT id, title, completed, priority, due_date FROM tasks WHERE project_id = ? AND id = ?');
const nextPosition = db.prepare('SELECT COALESCE(MAX(position), 0) + 1 AS position FROM task_positions WHERE project_id = ?');
const rememberPosition = db.prepare('INSERT INTO task_positions (task_id, project_id, position) VALUES (?, ?, ?)');
const getPosition = db.prepare('SELECT position FROM task_positions WHERE task_id = ? AND project_id = ?');
const createTask = db.prepare('INSERT INTO tasks (project_id, title, priority, position) VALUES (?, ?, ?, ?)');
const moveTask = db.prepare('UPDATE tasks SET project_id = ?, position = ? WHERE project_id = ? AND id = ?');

function transaction(action) {
  db.exec('BEGIN IMMEDIATE');
  try {
    const result = action();
    db.exec('COMMIT');
    return result;
  } catch (error) {
    db.exec('ROLLBACK');
    throw error;
  }
}
const updateTask = db.prepare('UPDATE tasks SET completed = ? WHERE project_id = ? AND id = ?');
const renameTask = db.prepare('UPDATE tasks SET title = ? WHERE project_id = ? AND id = ?');
const prioritizeTask = db.prepare('UPDATE tasks SET priority = ? WHERE project_id = ? AND id = ?');
const setDueDate = db.prepare('UPDATE tasks SET due_date = ? WHERE project_id = ? AND id = ?');
const taskData = (task) => ({ ...task, completed: Boolean(task.completed) });
const assets = new Map([
  ['/', ['text/html; charset=utf-8', readFileSync(new URL('./public/index.html', import.meta.url))]],
  ['/app.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./public/app.js', import.meta.url))]],
  ['/style.css', ['text/css; charset=utf-8', readFileSync(new URL('./public/style.css', import.meta.url))]],
]);

function json(res, status, data) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(data));
}

async function readBody(req) {
  let body = '';
  for await (const chunk of req) {
    body += chunk;
    if (Buffer.byteLength(body) > 65536) {
      throw Object.assign(new Error('Request is too large'), { status: 413 });
    }
  }
  try { return JSON.parse(body); }
  catch { throw Object.assign(new Error('Invalid JSON'), { status: 400 }); }
}

function validDueDate(value) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const [year, month, day] = value.split('-').map(Number);
  if (year < 1 || month < 1 || month > 12) return false;
  const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return day >= 1 && day <= days[month - 1];
}

const server = http.createServer(async (req, res) => {
  try {
    const path = new URL(req.url, 'http://localhost').pathname;
    if (req.method === 'GET' && path === '/health') return json(res, 200, { status: 'ok' });
    if (req.method === 'GET' && path === '/api/projects') return json(res, 200, listProjects.all());
    const match = path.match(/^\/api\/projects\/(\d+)$/);
    if (req.method === 'GET' && match) {
      const project = getProject.get(match[1]);
      return json(res, project ? 200 : 404, project || { error: 'Project not found' });
    }
    if (req.method === 'PATCH' && match) {
      if (!getProject.get(match[1])) return json(res, 404, { error: 'Project not found' });
      const input = await readBody(req);
      if (Object.hasOwn(input || {}, 'default_priority')) {
        if (getProject.get(match[1]).archived) return json(res, 409, { error: 'Archived project' });
        if (!['Low', 'Normal', 'High'].includes(input.default_priority)) {
          return json(res, 400, { error: 'Priority must be Low, Normal, or High' });
        }
        setDefaultPriority.run(input.default_priority, match[1]);
        return json(res, 200, getProject.get(match[1]));
      }
      if (Object.hasOwn(input || {}, 'name')) {
        if (getProject.get(match[1]).archived) return json(res, 409, { error: 'Archived project' });
        const name = typeof input.name === 'string' ? input.name.trim() : '';
        if (!name) return json(res, 400, { error: 'Project name is required' });
        renameProject.run(name, match[1]);
        return json(res, 200, getProject.get(match[1]));
      }
      if (typeof input?.archived !== 'boolean') return json(res, 400, { error: 'Archive state must be a boolean' });
      updateProject.run(Number(input.archived), match[1]);
      return json(res, 200, getProject.get(match[1]));
    }
    if (req.method === 'POST' && path === '/api/projects') {
      const input = await readBody(req);
      const name = typeof input?.name === 'string' ? input.name.trim() : '';
      if (!name) return json(res, 400, { error: 'Project name is required' });
      const result = createProject.run(name);
      return json(res, 201, getProject.get(Number(result.lastInsertRowid)));
    }
    const taskMatch = path.match(/^\/api\/projects\/(\d+)\/tasks(?:\/(\d+))?$/);
    if (taskMatch) {
      const [, projectId, taskId] = taskMatch;
      const project = getProject.get(projectId);
      if (!project) return json(res, 404, { error: 'Project not found' });
      if (req.method === 'GET' && !taskId) {
        return json(res, 200, listTasks.all(projectId).map(taskData));
      }
      if (req.method === 'POST' && !taskId) {
        const input = await readBody(req);
        const currentProject = getProject.get(projectId);
        if (currentProject.archived) return json(res, 409, { error: 'Archived project' });
        const title = typeof input?.title === 'string' ? input.title.trim() : '';
        if (!title) return json(res, 400, { error: 'Task title is required' });
        const taskId = transaction(() => {
          const position = nextPosition.get(projectId).position;
          const result = createTask.run(projectId, title, currentProject.default_priority, position);
          const id = Number(result.lastInsertRowid);
          rememberPosition.run(id, projectId, position);
          return id;
        });
        return json(res, 201, taskData(getTask.get(projectId, taskId)));
      }
      if (req.method === 'PATCH' && taskId) {
        if (!getTask.get(projectId, taskId)) return json(res, 404, { error: 'Task not found' });
        const input = await readBody(req);
        if (getProject.get(projectId).archived) return json(res, 409, { error: 'Archived project' });
        if (Object.hasOwn(input || {}, 'project_id')) {
          if (!Number.isSafeInteger(input.project_id) || input.project_id < 1 || input.project_id === Number(projectId)) {
            return json(res, 400, { error: 'Choose another active destination project' });
          }
          const destination = getProject.get(input.project_id);
          if (!destination) return json(res, 404, { error: 'Destination project not found' });
          if (destination.archived) return json(res, 409, { error: 'Archived project' });
          // Recheck ownership after reading the request body, in case another request moved it.
          if (!getTask.get(projectId, taskId)) return json(res, 404, { error: 'Task not found' });
          transaction(() => {
            let remembered = getPosition.get(taskId, destination.id);
            if (!remembered) {
              remembered = nextPosition.get(destination.id);
              rememberPosition.run(taskId, destination.id, remembered.position);
            }
            moveTask.run(destination.id, remembered.position, projectId, taskId);
          });
          return json(res, 200, taskData(getTask.get(destination.id, taskId)));
        }
        if (Object.hasOwn(input || {}, 'due_date')) {
          const date = typeof input.due_date === 'string' ? input.due_date.trim() : null;
          if (date === null || (date !== '' && !validDueDate(date))) {
            return json(res, 400, { error: 'Due date must be a valid YYYY-MM-DD date' });
          }
          setDueDate.run(date, projectId, taskId);
          return json(res, 200, taskData(getTask.get(projectId, taskId)));
        }
        if (Object.hasOwn(input || {}, 'priority')) {
          if (!['Low', 'Normal', 'High'].includes(input.priority)) {
            return json(res, 400, { error: 'Priority must be Low, Normal, or High' });
          }
          prioritizeTask.run(input.priority, projectId, taskId);
          return json(res, 200, taskData(getTask.get(projectId, taskId)));
        }
        if (Object.hasOwn(input || {}, 'title')) {
          const title = typeof input.title === 'string' ? input.title.trim() : '';
          if (!title) return json(res, 400, { error: 'Task title is required' });
          renameTask.run(title, projectId, taskId);
          return json(res, 200, taskData(getTask.get(projectId, taskId)));
        }
        if (typeof input?.completed !== 'boolean') return json(res, 400, { error: 'Completion must be a boolean' });
        updateTask.run(Number(input.completed), projectId, taskId);
        return json(res, 200, taskData(getTask.get(projectId, taskId)));
      }
    }
    if (req.method === 'GET') {
      const asset = assets.get(/^\/projects\/\d+$/.test(path) ? '/' : path);
      if (asset) {
        res.writeHead(200, { 'Content-Type': asset[0], 'Cache-Control': 'no-store' });
        return res.end(asset[1]);
      }
    }
    json(res, 404, { error: 'Not found' });
  } catch (error) {
    if (error.status) return json(res, error.status, { error: error.message });
    console.error(error);
    if (!res.headersSent) json(res, 500, { error: 'Unable to complete request' });
    else res.end();
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0', () => {
  console.log(`Workboard listening on port ${server.address().port}`);
});
for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => server.close(() => { db.close(); process.exit(0); }));
}
const listView = document.querySelector('#projects-view');
const detailView = document.querySelector('#project-view');
const list = document.querySelector('#project-list');
const error = document.querySelector('#error');
const form = document.querySelector('#project-form');
const input = document.querySelector('#project-name');
const projectFilter = document.querySelector('#project-filter');
const archivedNotice = document.querySelector('#archived-notice');
const taskForm = document.querySelector('#task-form');
const taskInput = document.querySelector('#task-title');
const taskFilter = document.querySelector('#task-filter');
const priorityFilter = document.querySelector('#priority-filter');
const dueRangeForm = document.querySelector('#due-range-form');
const dueFrom = document.querySelector('#due-from');
const dueThrough = document.querySelector('#due-through');
let appliedDueFrom = '';
let appliedDueThrough = '';
const defaultTaskPriority = document.querySelector('#default-task-priority');
const taskList = document.querySelector('#task-list');
const detailError = document.querySelector('#detail-error');
const renameForm = document.querySelector('#rename-form');
const renameInput = document.querySelector('#new-project-name');
const renameButton = renameForm.querySelector('button');
let activeProjectId = null;
let archivedProject = false;
let savedDefaultPriority = 'Normal';
let tasks = [];
let destinationProjects = [];
let renderVersion = 0;

async function request(path, options) {
  const response = await fetch(path, options);
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || 'Unable to complete request');
  return data;
}

function showError(element, message) {
  element.textContent = message;
  element.hidden = !message;
}

function navigate(path) {
  history.pushState({}, '', path);
  render();
}

async function render() {
  const version = ++renderVersion;
  const currentPath = location.pathname;
  const match = currentPath.match(/^\/projects\/(\d+)$/);
  listView.hidden = Boolean(match);
  detailView.hidden = !match;
  document.title = 'Workboard';
  activeProjectId = null;
  archivedProject = false;
  defaultTaskPriority.disabled = true;
  archivedNotice.hidden = true;
  renameForm.hidden = true;
  renameInput.disabled = true;
  renameButton.disabled = true;
  taskForm.querySelector('button').disabled = true;
  tasks = [];
  destinationProjects = [];
  taskList.replaceChildren();
  taskInput.value = '';
  taskFilter.value = 'All';
  priorityFilter.value = 'All';
  dueFrom.value = '';
  dueThrough.value = '';
  appliedDueFrom = '';
  appliedDueThrough = '';
  document.querySelector('#task-controls').hidden = true;
  if (match) {
    const title = document.querySelector('#project-title');
    title.textContent = '';
    showError(detailError, '');
    try {
      const project = await request(`/api/projects/${match[1]}`);
      if (version !== renderVersion) return;
      title.textContent = project.name;
      archivedProject = Boolean(project.archived);
      archivedNotice.hidden = !archivedProject;
      taskForm.querySelector('button').disabled = archivedProject;
      document.title = `${project.name} · Workboard`;
      const savedTasks = await request(`/api/projects/${project.id}/tasks`);
      const projects = await request('/api/projects');
      if (version !== renderVersion) return;
      destinationProjects = projects.filter((item) => !item.archived && item.id !== project.id);
      activeProjectId = project.id;
      savedDefaultPriority = project.default_priority;
      defaultTaskPriority.value = savedDefaultPriority;
      defaultTaskPriority.disabled = archivedProject;
      renameInput.value = project.name;
      renameInput.disabled = archivedProject;
      renameButton.disabled = archivedProject;
      renameForm.hidden = false;
      tasks = savedTasks;
      document.querySelector('#task-controls').hidden = false;
      renderTasks();
    } catch (err) { if (version === renderVersion) showError(detailError, err.message); }
    return;
  }
  showError(error, '');
  try {
    const projects = await request('/api/projects');
    if (version !== renderVersion) return;
    list.replaceChildren();
    const visibleProjects = projects.filter((project) => Boolean(project.archived) === (projectFilter.value === 'Archived'));
    for (const project of visibleProjects) {
      const row = document.createElement('div');
      row.className = 'project-row';
      row.dataset.testid = 'project-row';
      const name = document.createElement('span');
      name.textContent = project.name;
      const summary = document.createElement('span');
      summary.className = 'project-summary';
      summary.dataset.testid = 'project-summary';
      summary.textContent = `${project.completed}/${project.total} completed`;
      const information = document.createElement('div');
      information.className = 'project-information';
      information.append(name, summary);
      const open = document.createElement('button');
      open.type = 'button';
      open.className = 'secondary';
      open.textContent = 'Open project';
      open.addEventListener('click', () => navigate(`/projects/${project.id}`));
      const archive = document.createElement('button');
      archive.type = 'button';
      archive.className = 'secondary';
      archive.textContent = project.archived ? 'Restore project' : 'Archive project';
      archive.addEventListener('click', async () => {
        archive.disabled = true;
        showError(error, '');
        try {
          await request(`/api/projects/${project.id}`, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ archived: !project.archived }),
          });
          await render();
        } catch (err) { showError(error, err.message); }
        finally { archive.disabled = false; }
      });
      const actions = document.createElement('div');
      actions.className = 'project-actions';
      actions.append(open, archive);
      row.append(information, actions);
      list.append(row);
    }
    const empty = document.querySelector('#empty');
    empty.hidden = visibleProjects.length > 0;
    empty.textContent = projectFilter.value === 'Archived' ? 'No archived projects.' : 'No active projects. Create a project above.';
  } catch (err) { showError(error, err.message); }
}

function renderTasks() {
  taskList.replaceChildren();
  for (const task of tasks) {
    if (taskFilter.value === 'Open' && task.completed) continue;
    if (taskFilter.value === 'Completed' && !task.completed) continue;
    if (priorityFilter.value !== 'All' && task.priority !== priorityFilter.value) continue;
    if (appliedDueFrom || appliedDueThrough) {
      if (!task.due_date) continue;
      if (appliedDueFrom && task.due_date < appliedDueFrom) continue;
      if (appliedDueThrough && task.due_date > appliedDueThrough) continue;
    }
    const row = document.createElement('div');
    row.className = 'task-row';
    row.dataset.testid = 'task-row';
    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.checked = task.completed;
    checkbox.disabled = archivedProject;
    checkbox.setAttribute('aria-label', `Complete ${task.title}`);
    const title = document.createElement('span');
    title.textContent = task.title;
    checkbox.addEventListener('change', async () => {
      const projectId = activeProjectId;
      const version = renderVersion;
      checkbox.disabled = true;
      showError(detailError, '');
      try {
        const saved = await request(`/api/projects/${projectId}/tasks/${task.id}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ completed: checkbox.checked }),
        });
        if (version !== renderVersion) return;
        tasks = tasks.map((item) => item.id === saved.id ? saved : item);
        renderTasks();
      } catch (err) {
        if (version !== renderVersion) return;
        checkbox.checked = task.completed;
        showError(detailError, err.message);
      } finally { checkbox.disabled = archivedProject; }
    });
    const information = document.createElement('div');
    information.className = 'task-information';
    information.append(checkbox, title);
    const priorityControls = document.createElement('div');
    const priorityLabel = document.createElement('label');
    priorityLabel.htmlFor = `task-priority-${task.id}`;
    priorityLabel.textContent = 'Task priority';
    const priority = document.createElement('select');
    priority.id = priorityLabel.htmlFor;
    for (const value of ['Low', 'Normal', 'High']) {
      const option = document.createElement('option');
      option.value = value;
      option.textContent = value;
      priority.append(option);
    }
    priority.value = task.priority;
    priority.disabled = archivedProject;
    priority.addEventListener('change', async () => {
      if (archivedProject || activeProjectId === null) return;
      const projectId = activeProjectId;
      const version = renderVersion;
      priority.disabled = true;
      showError(detailError, '');
      try {
        const saved = await request(`/api/projects/${projectId}/tasks/${task.id}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ priority: priority.value }),
        });
        if (version !== renderVersion) return;
        tasks = tasks.map((item) => item.id === saved.id ? saved : item);
        renderTasks();
      } catch (err) {
        if (version !== renderVersion) return;
        priority.value = task.priority;
        showError(detailError, err.message);
      } finally { priority.disabled = archivedProject; }
    });
    priorityControls.append(priorityLabel, priority);
    const taskRenameForm = document.createElement('form');
    taskRenameForm.className = 'task-rename-form';
    const label = document.createElement('label');
    label.htmlFor = `new-task-title-${task.id}`;
    label.textContent = 'New task title';
    const newTitle = document.createElement('input');
    newTitle.id = label.htmlFor;
    newTitle.type = 'text';
    newTitle.value = task.title;
    newTitle.disabled = archivedProject;
    const rename = document.createElement('button');
    rename.type = 'submit';
    rename.textContent = 'Rename task';
    rename.disabled = archivedProject;
    const controls = document.createElement('div');
    controls.className = 'form-controls';
    controls.append(newTitle, rename);
    taskRenameForm.append(label, controls);
    taskRenameForm.addEventListener('submit', async (event) => {
      event.preventDefault();
      if (archivedProject || activeProjectId === null) return;
      const title = newTitle.value.trim();
      if (!title) {
        showError(detailError, 'Task title is required');
        newTitle.focus();
        return;
      }
      const projectId = activeProjectId;
      const version = renderVersion;
      rename.disabled = true;
      showError(detailError, '');
      try {
        const saved = await request(`/api/projects/${projectId}/tasks/${task.id}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ title }),
        });
        if (version !== renderVersion) return;
        tasks = tasks.map((item) => item.id === saved.id ? saved : item);
        renderTasks();
      } catch (err) { if (version === renderVersion) showError(detailError, err.message); }
      finally { rename.disabled = archivedProject; }
    });
    const dueDateForm = document.createElement('form');
    dueDateForm.className = 'task-due-date-form';
    const dueDateLabel = document.createElement('label');
    dueDateLabel.htmlFor = `task-due-date-${task.id}`;
    dueDateLabel.textContent = 'Task due date';
    const dueDate = document.createElement('input');
    dueDate.id = dueDateLabel.htmlFor;
    dueDate.type = 'text';
    dueDate.placeholder = 'YYYY-MM-DD';
    dueDate.value = task.due_date || '';
    dueDate.disabled = archivedProject;
    const saveDueDate = document.createElement('button');
    saveDueDate.type = 'submit';
    saveDueDate.textContent = 'Save due date';
    saveDueDate.disabled = archivedProject;
    const dueDateControls = document.createElement('div');
    dueDateControls.className = 'form-controls';
    dueDateControls.append(dueDate, saveDueDate);
    dueDateForm.append(dueDateLabel, dueDateControls);
    dueDateForm.addEventListener('submit', async (event) => {
      event.preventDefault();
      if (archivedProject || activeProjectId === null) return;
      const projectId = activeProjectId;
      const version = renderVersion;
      saveDueDate.disabled = true;
      showError(detailError, '');
      try {
        const saved = await request(`/api/projects/${projectId}/tasks/${task.id}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ due_date: dueDate.value }),
        });
        if (version !== renderVersion) return;
        tasks = tasks.map((item) => item.id === saved.id ? saved : item);
        renderTasks();
      } catch (err) { if (version === renderVersion) showError(detailError, err.message); }
      finally { saveDueDate.disabled = archivedProject; }
    });
    const moveForm = document.createElement('form');
